<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FlyBoard</title>
<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b1220;color:#e5eefc;font:14px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1280px;margin:26px auto;padding:0 22px}h1{margin:0;color:#7dd3fc;font-size:26px}.sub{color:#9fb0c8;margin:6px 0 22px}.card{background:#111c2e;border:1px solid #263957;border-radius:12px;padding:18px;margin:14px 0}.card h2{margin:0 0 14px;font-size:18px}.grid{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:12px}.wide{grid-column:span 2}label{display:block;color:#aac0d9;margin:0 0 6px}input,textarea,select{width:100%;padding:9px 10px;border-radius:7px;border:1px solid #38516f;background:#0b1424;color:#fff}textarea{resize:vertical}button{cursor:pointer;background:#159eaa;color:#fff;border:0;border-radius:7px;padding:9px 14px;margin:10px 8px 0 0}button.secondary{background:#334a68}button.danger{background:#9b3d58}.hint{color:#8ea4c0;font-size:12px;margin-top:6px}.msg{color:#7dd3fc;margin-left:8px}.err{color:#fda4af}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:880px}td,th{text-align:left;padding:9px;border-bottom:1px solid #263957;white-space:nowrap}th{color:#a9c4e4;font-weight:600}.badge{display:inline-block;border-radius:999px;padding:3px 9px;background:#24415e}.ok{background:#145c4a}.muted{color:#9fb0c8}.stats{display:flex;gap:18px;flex-wrap:wrap;margin:10px 0}.stat{background:#0b1424;border:1px solid #263957;border-radius:8px;padding:10px 14px}.stat b{display:block;font-size:20px;color:#7dd3fc}.url{max-width:300px;overflow:hidden;text-overflow:ellipsis;display:inline-block;vertical-align:bottom}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.nav button{margin:0;background:#1c2c45}.nav button.active{background:#159eaa}.page{display:none}.page.active{display:block}.check-cell{width:34px;text-align:center}
@media(max-width:800px){.grid{grid-template-columns:1fr}.wide{grid-column:span 1}}
</style></head>
<body><div class="wrap"><h1>FlyBoard</h1><div class="sub">独立上游订阅 · 上游用户管理 · 上游节点隔离 · 主用户订阅防分享</div><div class="nav"><button class="active" data-page="upstream" onclick="showPage('upstream',this)">上游配置</button><button data-page="main-antishare" onclick="showPage('main-antishare',this)">主用户防分享</button><button data-page="main-users" onclick="showPage('main-users',this)">主用户管理</button><button data-page="clients" onclick="showPage('clients',this)">客户端</button><button data-page="nodes" onclick="showPage('nodes',this)">节点列表</button><button data-page="logs" onclick="showPage('logs',this)">拦截日志</button></div>
<section id="page-upstream" class="page active"><div class="card"><h2>拉取上游订阅</h2><div class="grid">
<div><label>启用</label><select id="pullEnabled"><option value="1">启用</option><option value="0">停用</option></select></div>
<div><label>超时（秒）</label><input id="pullTimeout" type="number" min="3" value="30"></div>
<div><label>最大内容大小（字节）</label><input id="maxBytes" type="number" min="1024" value="524288"></div>
<div><label>User-Agent（可选）</label><input id="pullUA" placeholder="留空则沿用订阅客户端 UA"></div>
<div class="wide"><label>多上游节点（每行一个：名称|URL|启用，也支持直接每行 URL）</label><textarea id="multiUrls" rows="5" placeholder="上游1|https://example.com/s/xxx|1"></textarea><div class="hint">URL 支持 {token}、{userid}、{email}、{uuid} 占位符；每行会建立一个独立上游用户。</div></div>
<div><label>默认上游用户邮箱（可选）</label><input id="defaultEmail" placeholder="user@example.com"></div><div><label>默认 Token（可选）</label><input id="defaultToken"></div><div><label>默认用户 ID（可选）</label><input id="defaultUserId"></div><div><label>默认 UUID（可选）</label><input id="defaultUuid"></div>
</div><button onclick="saveMulti()">保存上游配置</button><button class="secondary" onclick="pullAll()">测试拉取</button><button class="secondary" onclick="addLine()">增加一行上游</button><span id="pullMsg" class="msg"></span></div>
<div class="card"><h2>上游用户管理</h2><div class="muted">独立上游用户，不使用主用户表；只用于拉取上游订阅节点。节点和在线状态使用 FlyBoard 独立存储，不影响主用户。</div><div class="stats"><div class="stat"><b id="userCount">0</b>上游用户</div><div class="stat"><b id="nodeCount">0</b>上游节点</div></div><button onclick="loadUsers()">刷新列表</button><button class="secondary" onclick="pullAll()">拉取全部启用用户</button><button class="secondary" onclick="pullSelected()">用选中用户测试拉取</button><span id="userMsg" class="msg"></span><div class="table-wrap"><table><thead><tr><th></th><th>ID</th><th>邮箱/名称</th><th>状态</th><th>流量</th><th>到期</th><th>节点数</th><th>最后拉取</th><th>订阅地址</th><th>操作</th></tr></thead><tbody id="users"></tbody></table></div></div>
</section><section id="page-main-antishare" class="page"><div class="card"><h2>主用户订阅防分享</h2><div class="muted">保护主用户标准订阅地址（例如 /s/{token}）。订阅内的全部节点共用同一套设备登记；同一主用户从超过限制的不同设备请求订阅时会被拒绝。</div><div class="grid"><div><label>功能状态</label><select id="mainAntiShareEnabled"><option value="1">启用</option><option value="0">停用</option></select></div><div><label>允许设备数</label><input id="mainAntiShareLimit" type="number" min="1" max="50" value="1"><div class="hint">按 IP + User-Agent 识别，建议 1～2 台。</div></div><div><label>设备记忆窗口（秒）</label><input id="mainAntiShareWindow" type="number" min="60" max="2592000" value="300"><div class="hint">可自定义，单位秒；默认 300 秒，窗口内的新设备会被拦截，窗口释放时同步释放节点在线设备占位。</div></div><div><label>XBoard 整个后台面板白名单</label><select id="panelWhitelistEnabled"><option value="0">关闭</option><option value="1">开启</option></select></div><div class="wide"><label>XBoard 后台 IP/CIDR 白名单（可选）</label><textarea id="mainAntiShareWhitelist" rows="2" placeholder="每行或逗号分隔一个 IP"></textarea><div class="hint">开关开启后生效；开启后保护整个 XBoard 后台入口和后台 API；不是主用户订阅白名单。</div></div><div class="wide"><label>XBoard 面板拦截纪律</label><textarea id="mainPanelBlockPolicy" rows="6" placeholder="记录面板白名单的拦截规则和操作纪律"></textarea><div class="hint">只作为管理面板说明/纪律记录，不改变已修好的订阅或节点设备限制逻辑。</div></div></div><button onclick="saveMainAntiShare()">保存主用户防分享设置</button><span id="mainAntiShareMsg" class="msg"></span></div><div class="card"><h2>生效范围说明</h2><div class="muted">此功能只控制主用户订阅地址的访问，不改变主用户账号、套餐或节点配置。若还要限制主用户同时在线的实际连接设备，请在主用户的 device_limit 中设置，并确保节点端使用支持跨节点设备限制的版本。FlyBoard 独立客户端仍使用“客户端”页面自己的设备数限制。</div></div></section><section id="page-main-users" class="page"><div class="card"><h2>主用户管理 · 全节点防分享</h2><div class="muted">这里管理的是 XBoard 主用户的标准订阅。一个用户订阅里的所有节点共用同一份设备登记；设置为 1 时，用户从节点 A 登记后，再从节点 B 使用另一台设备会被拦截。0 表示不限设备。</div><div class="grid"><div class="wide"><label>按邮箱或用户 ID 搜索</label><input id="mainUserSearch" placeholder="留空显示最近用户" onkeydown="if(event.key==='Enter')loadMainUsers()"></div><div><label>显示数量</label><input id="mainUserLimit" type="number" min="1" max="100" value="50"></div></div><button onclick="loadMainUsers()">刷新主用户</button><span id="mainUsersMsg" class="msg"></span><div class="table-wrap"><table><thead><tr><th>ID</th><th>邮箱</th><th>状态/到期</th><th>设备限制</th><th>当前设备</th><th>设备 IP</th><th>订阅节点</th><th>订阅地址</th><th>白名单</th><th>操作</th></tr></thead><tbody id="mainUsers"></tbody></table></div></div><div class="card"><h2>使用说明</h2><div class="muted">设备限制由节点端在上报设备时执行，并通过 Redis 在所有节点之间共享。这里的“清理设备”只释放该用户当前登记的设备，不会删除账号、订阅或流量数据；用户重新连接后会重新登记。</div></div></section><section id="page-clients" class="page"><div class="card"><h2>客户端管理与分享</h2><div class="muted">客户端只读取已拉取的上游节点；可单独设置到期时间、额度、在线设备数，并分享订阅地址或二维码。</div><input id="clientId" type="hidden"><div class="grid"><div><label>名称</label><input id="clientName" placeholder="客户 A"></div><div><label>状态</label><select id="clientEnabled"><option value="1">启用</option><option value="0">停用</option></select></div><div><label>到期时间（可选）</label><input id="clientExpires" type="datetime-local"></div><div><label>流量额度（字节，0=不限）</label><input id="clientTraffic" type="number" min="0" value="0"></div><div><label>在线设备数</label><input id="clientDevices" type="number" min="1" max="100" value="1"></div><div><label>设备窗口（秒）</label><input id="clientWindow" type="number" min="60" value="300"><div class="hint">可自定义，单位秒；默认 300 秒。</div></div><div class="wide"><label>备注</label><input id="clientNote"></div></div><button id="saveClientButton" onclick="saveClient()">创建客户端</button><button id="cancelClientButton" class="secondary" onclick="resetClientForm()" style="display:none">取消编辑</button><button class="secondary" onclick="loadClients()">刷新客户端</button><span id="clientMsg" class="msg"></span><div class="table-wrap"><table><thead><tr><th>ID</th><th>名称</th><th>状态</th><th>到期</th><th>额度/已用</th><th>设备</th><th>订阅分享</th><th>二维码</th><th>操作</th></tr></thead><tbody id="clients"></tbody></table></div></div>
</section><section id="page-nodes" class="page"><div class="card"><h2>仅上游用户节点</h2><div class="muted">此列表只来自 flyboard_upstream_nodes，明确不会查询 v2_server 或主用户节点。</div><button onclick="loadNodes()">刷新节点</button><div class="table-wrap"><table><thead><tr><th>上游用户</th><th>节点名称</th><th>类型</th><th>地址</th><th>端口</th><th>状态</th></tr></thead><tbody id="nodes"></tbody></table></div></div>
</section><section id="page-logs" class="page"><div class="card"><h2>拦截日志</h2><div class="muted">日志仅用于查看拦截记录，可手动删除；删除不会影响客户端或节点。</div><button class="secondary" onclick="loadLogs()">刷新日志</button><button class="secondary" onclick="dropSelectedLogs()">删除选中</button><button class="danger" onclick="clearLogs()">清空全部日志</button><span id="logMsg" class="msg"></span><div class="table-wrap"><table><thead><tr><th class="check-cell"><input type="checkbox" id="logAll" onchange="toggleAllLogs(this)"></th><th>时间</th><th>用户</th><th>客户端</th><th>IP</th><th>动作</th><th>原因</th><th>操作</th></tr></thead><tbody id="logs"></tbody></table></div></div></section></div>
<script>
const securePath=@json($secure_path), apiBase='/api/v2/'+securePath+'/flyboard';
function accessToken(){try{const r=localStorage.getItem('XBOARD_ACCESS_TOKEN'),p=r?JSON.parse(r):null;return p?.value||r||''}catch(_){return localStorage.getItem('XBOARD_ACCESS_TOKEN')||''}}
async function api(path,opt={}){const h={'Content-Type':'application/json',...(opt.headers||{})},t=accessToken();if(t)h.Authorization=t;const r=await fetch(apiBase+path,{credentials:'same-origin',...opt,headers:h}),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.message||('HTTP '+r.status));return j.data}
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function addLine(){multiUrls.value+=(multiUrls.value?'\n':'')+'上游'+(multiUrls.value.split('\n').length+1)+'|https://|1'}
function fmtBytes(n){n=+n||0;return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':n<1073741824?(n/1048576).toFixed(1)+' MB':(n/1073741824).toFixed(2)+' GB'}
function fmtTraffic(u){return fmtBytes((+u.upload||0)+(+u.download||0))+' / '+fmtBytes(u.transfer_enable)}
async function saveMulti(){const lines=multiUrls.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{for(const line of lines){let [name,url,enabled]=line.split('|');if(!url)url=name,name='上游用户';await api('/upstreams/save',{method:'POST',body:JSON.stringify({name:name||'上游用户',email:defaultEmail.value,token:defaultToken.value,user_id:defaultUserId.value,uuid:defaultUuid.value,subscribe_url:url,enabled:enabled!=='0',user_agent:pullUA.value})})}pullMsg.textContent=' 上游配置已保存';await loadUsers()}catch(e){pullMsg.textContent=' '+e.message;pullMsg.className='msg err'}}
async function pullAll(){try{const j=await api('/upstreams/pull',{method:'POST',body:JSON.stringify({all:true})});pullMsg.textContent=` 拉取完成：上游 ${j.users} 个，有用节点 ${j.nodes} 条；`+j.results.map(x=>x.status==='success'?`${x.name} ${x.nodes} 条${x.rejected_nodes?`，删除无用 ${x.rejected_nodes} 条`:''}`:`${x.name} 失败`).join('，');await loadUsers();await loadNodes()}catch(e){pullMsg.textContent=' '+e.message;pullMsg.className='msg err'}}
async function pullSelected(){const id=document.querySelector('input[name="pick"]:checked')?.value;if(!id)return userMsg.textContent=' 请先选择上游用户';try{const j=await api('/upstreams/pull',{method:'POST',body:JSON.stringify({id})});userMsg.textContent=' 测试拉取完成：'+j.nodes+' 个节点';await loadUsers();await loadNodes()}catch(e){userMsg.textContent=' '+e.message}}
async function loadUsers(){try{const a=await api('/upstreams');userCount.textContent=a.length;nodeCount.textContent=a.reduce((n,x)=>n+(+x.last_node_count||0),0);users.innerHTML=a.map(x=>`<tr><td><input type="radio" name="pick" value="${x.id}"></td><td>${x.id}</td><td>${esc(x.email||x.name)}<br><span class="muted">${esc(x.name)}</span></td><td><span class="badge ${x.enabled?'ok':''}">${x.enabled?'启用':'停用'}</span>${x.last_error?'<br><span class="err">拉取失败</span>':''}</td><td>${fmtTraffic(x)}</td><td>${esc(x.expired_at||'-')}</td><td>${x.last_node_count||0}</td><td>${esc(x.last_pulled_at||'-')}</td><td><span class="url" title="${esc(x.subscribe_url)}">${esc(x.subscribe_url)}</span></td><td><button onclick="pullOne(${x.id})">拉取</button><button class="danger" onclick="dropUser(${x.id})">删除</button></td></tr>`).join('')||'<tr><td colspan="10" class="muted">暂无上游用户</td></tr>'}catch(e){userMsg.textContent=' '+e.message}}
async function pullOne(id){try{await api('/upstreams/pull',{method:'POST',body:JSON.stringify({id})});await loadUsers();await loadNodes()}catch(e){alert(e.message)}}
async function dropUser(id){if(!confirm('确认删除上游用户及其独立节点？'))return;await api('/upstreams/drop',{method:'POST',body:JSON.stringify({id})});await loadUsers();await loadNodes()}
function toLocalDateTime(value){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function resetClientForm(){clientId.value='';clientName.value='';clientEnabled.value='1';clientExpires.value='';clientTraffic.value='0';clientDevices.value='1';clientWindow.value='300';clientNote.value='';saveClientButton.textContent='创建客户端';cancelClientButton.style.display='none';clientMsg.textContent=''}
function editClient(x){clientId.value=x.id;clientName.value=x.name||'';clientEnabled.value=x.enabled?'1':'0';clientExpires.value=toLocalDateTime(x.expires_at);clientTraffic.value=+x.traffic_limit||0;clientDevices.value=+x.device_limit||1;clientWindow.value=+x.device_window||300;clientNote.value=x.note||'';saveClientButton.textContent='保存修改';cancelClientButton.style.display='inline-block';clientMsg.textContent=' 正在编辑客户端 #'+x.id;clientName.scrollIntoView({behavior:'smooth',block:'center'})}
async function saveClient(){try{const id=+clientId.value||null;const payload={id,name:clientName.value,enabled:clientEnabled.value==='1',expires_at:clientExpires.value?new Date(clientExpires.value).toISOString():null,traffic_limit:+clientTraffic.value||0,device_limit:+clientDevices.value||1,device_window:+clientWindow.value||300,note:clientNote.value};await api('/clients/save',{method:'POST',body:JSON.stringify(payload)});clientMsg.textContent=id?' 客户端已更新':' 客户端已创建';resetClientForm();await loadClients()}catch(e){clientMsg.textContent=' '+e.message;clientMsg.className='msg err'}}
async function loadClients(){try{const a=await api('/clients');clients.innerHTML=a.map(x=>`<tr><td>${x.id}</td><td>${esc(x.name)}</td><td><span class="badge ${x.enabled?'ok':''}">${x.enabled?'启用':'停用'}</span></td><td>${esc(x.expires_at||'不限')}</td><td>${fmtBytes(x.traffic_limit)} / ${fmtBytes(x.traffic_used)}</td><td>${x.device_limit} 台</td><td><button onclick="copyText('${esc(x.subscription_url)}')">复制订阅</button><span class="url" title="${esc(x.subscription_url)}">${esc(x.subscription_url)}</span></td><td><a href="${esc(x.qr_url)}" target="_blank">打开二维码</a></td><td><button onclick='editClient(${JSON.stringify(x).replace(/'/g,"&#39;")})'>编辑</button><button class="danger" onclick="dropClient(${x.id})">删除</button></td></tr>`).join('')||'<tr><td colspan="9" class="muted">暂无客户端</td></tr>'}catch(e){clientMsg.textContent=' '+e.message;clientMsg.className='msg err'}}
async function copyText(v){try{await navigator.clipboard.writeText(v);clientMsg.textContent=' 已复制订阅地址'}catch(_){prompt('复制订阅地址',v)}}
async function dropClient(id){if(!confirm('确认删除此客户端？'))return;await api('/clients/drop',{method:'POST',body:JSON.stringify({id})});await loadClients()}
async function loadNodes(){try{const a=await api('/nodes');nodes.innerHTML=a.map(x=>`<tr><td>${esc(x.email||x.upstream_name)}</td><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td>${esc(x.address)}</td><td>${x.port||'-'}</td><td><span class="badge ${x.enabled?'ok':''}">${x.enabled?'启用':'停用'}</span></td></tr>`).join('')||'<tr><td colspan="6" class="muted">暂无上游节点</td></tr>'}catch(e){nodes.innerHTML='<tr><td colspan="6" class="err">'+esc(e.message)+'</td></tr>'}}
async function loadMainUsers(){try{const q=encodeURIComponent(mainUserSearch.value.trim()),limit=+mainUserLimit.value||50;const a=await api('/main-users?q='+q+'&limit='+limit);mainUsers.innerHTML=a.map(x=>{const status=x.banned?'封禁':'正常';const expiry=x.expired_at?new Date(x.expired_at*1000).toLocaleString():'长期';const ips=(x.devices||[]).map(esc).join('<br>')||'<span class="muted">暂无</span>';const wl=x.main_user_whitelist||{};const wlOn=!!wl.enabled;const wlNote=wl.note||'';return `<tr><td>${x.id}</td><td>${esc(x.email)}</td><td>${status}<br><span class="muted">${esc(expiry)}</span></td><td><input id="limit-${x.id}" type="number" min="0" max="100" value="${x.device_limit??0}" style="width:78px"><br><span class="hint">0=不限</span></td><td>${x.online_count}</td><td>${ips}</td><td>${x.node_count??0} 个</td><td><button class="secondary" onclick="copyText('${esc(x.subscribe_url)}')">复制</button><span class="url" title="${esc(x.subscribe_url)}">${esc(x.subscribe_url)}</span></td><td><b style="color:${wlOn?'#22c55e':'#94a3b8'}">${wlOn?'已开启':'关闭'}</b><br><span class="hint">${esc(wlNote||'无备注')}</span><br><button onclick="toggleMainUserWhitelist(${x.id},${wlOn?0:1})">${wlOn?'关闭':'开启'}</button><button class="secondary" onclick="showMainUserWhitelistLogs(${x.id})">记录</button></td><td><button onclick="saveMainUser(${x.id})">保存限制</button><button class="danger" onclick="clearMainUser(${x.id})">清理设备</button></td></tr>`}).join('')||'<tr><td colspan="10" class="muted">暂无主用户</td></tr>'}catch(e){mainUsersMsg.textContent=' '+e.message;mainUsersMsg.className='msg err'}}
async function saveMainUser(id){try{const value=+document.getElementById('limit-'+id).value;if(value<0||value>100)throw Error('设备数必须是 0～100');await api('/main-users/save',{method:'POST',body:JSON.stringify({id,device_limit:value})});mainUsersMsg.textContent=' 主用户 #'+id+' 的全节点设备限制已保存';await loadMainUsers()}catch(e){mainUsersMsg.textContent=' '+e.message;mainUsersMsg.className='msg err'}}
async function toggleMainUserWhitelist(id,enabled){const note=prompt((enabled?'开启':'关闭')+'主用户白名单，可填写备注：','')||'';try{await api('/main-users/whitelist',{method:'POST',body:JSON.stringify({id,enabled:!!enabled,note})});mainUsersMsg.textContent=' 主用户 #'+id+' 白名单已'+(enabled?'开启':'关闭');mainUsersMsg.className='msg';await loadMainUsers()}catch(e){mainUsersMsg.textContent=' '+e.message;mainUsersMsg.className='msg err'}}
async function showMainUserWhitelistLogs(id){try{const rows=await api('/main-users/whitelist-logs?user_id='+id+'&limit=30');alert((rows||[]).map(x=>`#${x.id} ${x.created_at||''} ${x.action} ${x.reason||''} ${x.ip||''}`).join('\n')||'暂无白名单记录')}catch(e){mainUsersMsg.textContent=' '+e.message;mainUsersMsg.className='msg err'}}
async function clearMainUser(id){if(!confirm('确认清理主用户 #'+id+' 当前登记的全部设备？'))return;try{const r=await api('/main-users/clear-devices',{method:'POST',body:JSON.stringify({id})});mainUsersMsg.textContent=' 已清理 '+r.cleared+' 个设备登记';await loadMainUsers()}catch(e){mainUsersMsg.textContent=' '+e.message;mainUsersMsg.className='msg err'}}
async function loadMainAntiShare(){try{const x=await api('/settings');mainAntiShareEnabled.value=x.enabled?'1':'0';mainAntiShareLimit.value=+x.device_limit||1;mainAntiShareWindow.value=+x.window||300;panelWhitelistEnabled.value=x.panel_whitelist_enabled?'1':'0';mainAntiShareWhitelist.value=x.whitelist||'';mainPanelBlockPolicy.value=x.block_policy||''}catch(e){mainAntiShareMsg.textContent=' '+e.message;mainAntiShareMsg.className='msg err'}}
async function saveMainAntiShare(){try{await api('/settings',{method:'POST',body:JSON.stringify({enabled:mainAntiShareEnabled.value==='1',device_limit:+mainAntiShareLimit.value||1,window:+mainAntiShareWindow.value||300,panel_whitelist_enabled:panelWhitelistEnabled.value==='1',whitelist:mainAntiShareWhitelist.value,block_policy:mainPanelBlockPolicy.value})});mainAntiShareMsg.textContent=' 主用户订阅防分享设置已保存';mainAntiShareMsg.className='msg'}catch(e){mainAntiShareMsg.textContent=' '+e.message;mainAntiShareMsg.className='msg err'}}
function showPage(name,button){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+name));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x===button||x.dataset.page===name));if(name==='logs')loadLogs();if(name==='nodes')loadNodes();if(name==='clients')loadClients();if(name==='upstream')loadUsers();if(name==='main-antishare')loadMainAntiShare();if(name==='main-users')loadMainUsers()}
function toggleAllLogs(box){document.querySelectorAll('input[name="logPick"]').forEach(x=>x.checked=box.checked)}
function selectedLogIds(){return [...document.querySelectorAll('input[name="logPick"]:checked')].map(x=>+x.value)}
async function dropSelectedLogs(){const ids=selectedLogIds();if(!ids.length)return logMsg.textContent=' 请先选择日志';if(!confirm('确认删除选中的 '+ids.length+' 条日志？'))return;try{const r=await api('/logs/drop',{method:'POST',body:JSON.stringify({ids})});logMsg.textContent=' 已删除 '+r.deleted+' 条日志';await loadLogs()}catch(e){logMsg.textContent=' '+e.message;logMsg.className='msg err'}}
async function dropLog(id){if(!confirm('确认删除这条日志？'))return;try{await api('/logs/drop',{method:'POST',body:JSON.stringify({ids:[id]})});await loadLogs()}catch(e){logMsg.textContent=' '+e.message;logMsg.className='msg err'}}
async function clearLogs(){if(!confirm('确认清空全部拦截日志？此操作不可恢复。'))return;try{const r=await api('/logs/clear',{method:'POST'});logMsg.textContent=' 已清空 '+r.deleted+' 条日志';await loadLogs()}catch(e){logMsg.textContent=' '+e.message;logMsg.className='msg err'}}
async function loadLogs(){try{const a=await api('/logs');logAll.checked=false;logs.innerHTML=a.map(x=>`<tr><td class="check-cell"><input type="checkbox" name="logPick" value="${x.id}"></td><td>${esc(x.created_at)}</td><td>${x.user_id||'-'}</td><td>${esc(x.client_name||'-')}</td><td>${esc(x.ip||'-')}</td><td>${esc(x.action)}</td><td>${esc(x.reason||'-')}</td><td><button class="danger" onclick="dropLog(${x.id})">删除</button></td></tr>`).join('')||'<tr><td colspan="8" class="muted">暂无拦截日志</td></tr>'}catch(e){logMsg.textContent=' '+e.message;logMsg.className='msg err'}}
async function load(){try{await loadUsers();await loadMainAntiShare();await loadMainUsers()}catch(e){pullMsg.textContent=' '+e.message}}load();
</script></body></html>